// rand_ref_smoke — the seeded sequences, against a running Go.
// (math/rand/{rand,rng,normal,exp}.go, math/rand/v2/{rand,pcg}.go)
//
// Every expectation below is what a real Go 1.25.5 prints: the vectors
// are the output of `tools/gen_rand_ref.go` and `tools/gen_randv2_ref.go`
// run by `scripts/goref.sh`. The tables are GENERATED from that output
// rather than typed, so a transcription slip cannot make a wrong
// generator look right.
//
// A seeded generator is a DETERMINISTIC sequence, and Go's compatibility
// promise covers it: "the sequence of values generated by a given Source
// is guaranteed to remain stable". Anything that reproduces a shuffle, a
// sample, a fixture or a load pattern depends on that — and a generator
// that is off by one step still returns numbers in range, so nothing
// looks wrong until two sides compare notes.
//
// Neither package had a single provenance anchor: 49 functions in v1 and
// 24 in v2 matched Go by NAME only. That is the state `encoding/binary`
// was in when its Read and Write turned out to be stubs, and the state
// `math` was in when four of its special cases turned out to be wrong.
//
// Here the answer is that everything agrees — the ALFG's first six
// values for five seeds, all four bounded forms and their modulo bias
// handling, Float32/Float64, Perm, Shuffle, Read's byte stream, and both
// ziggurat generators (NormFloat64 and ExpFloat64) to the last bit; then
// in v2 the PCG stream, Lemire's bounded forms, and the marshalled
// generator state. That is the result worth recording, and the anchors
// are what turn it from a name match into something GOISH018 keeps
// checking.

#![no_std]
#![no_main]
#![allow(non_snake_case)]

extern crate alloc;
extern crate goish;

use goish::gostring::string;
use goish::math::rand;
use goish::math::rand::v2::{self as randv2, Source};
use goish::types::{byte, int};
use goish::{fmt, slice, syscall};

fn s(x: &str) -> string {
    return string::from_bytes(x.as_bytes());
}

// go: none — goish idiom: the smokes print one PASS/FAIL line per
//     numbered check; this is that line, hoisted.
fn report(failed: &mut int, ok: bool, n: &str, what: &str) {
    if ok {
        fmt::Println!("[", n, "]", what, "PASS");
    } else {
        fmt::Println!("[", n, "]", what, "FAIL");
        *failed += 1;
    }
}

// go: none — goish idiom: report one wrong draw against Go's, saying
//     which step of the sequence went wrong — the step matters, because
//     a generator that is merely OFFSET produces the right numbers in
//     the wrong places.
fn step(ok: &mut bool, what: &str, i: usize, got: i64, want: i64) {
    if got != want {
        fmt::Println!(
            "   ",
            s(what),
            fmt::Sprintf!("step %d got %d want %d", i as int, got, want)
        );
        *ok = false;
    }
}

fn stepu(ok: &mut bool, what: &str, i: usize, got: u64, want: u64) {
    if got != want {
        fmt::Println!(
            "   ",
            s(what),
            fmt::Sprintf!("step %d got %d want %d", i as int, got, want)
        );
        *ok = false;
    }
}

fn stepf(ok: &mut bool, what: &str, i: usize, got: f64, want: f64) {
    if got != want {
        fmt::Println!(
            "   ",
            s(what),
            fmt::Sprintf!("step %d got %v want %v", i as int, got, want)
        );
        *ok = false;
    }
}

