#[goish::main]
fn main() {
    let mut failed = 0;

    // 1. v1's ALFG: the first six Int63 draws for five seeds, including
    //    0 and -1. Seed 0 is not "no seed" in Go — it is a seed like any
    //    other, and its sequence is not the unseeded one.
    {
        let mut ok = true;
        let mut k = 0usize;
        while k < V1_INT63.len() {
            let (seed, want) = V1_INT63[k];
            let mut r = rand::New(rand::NewSource(seed));
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Int63", i, r.Int63(), want[i]);
                i += 1;
            }
            k += 1;
        }
        // The other widths off the same seed.
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_UINT32.len() {
            stepu(&mut ok, "Uint32", i, r.Uint32() as u64, V1_UINT32[i] as u64);
            i += 1;
        }
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_UINT64.len() {
            stepu(&mut ok, "Uint64", i, r.Uint64(), V1_UINT64[i]);
            i += 1;
        }
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_INT31.len() {
            step(&mut ok, "Int31", i, r.Int31() as i64, V1_INT31[i] as i64);
            i += 1;
        }
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_INT.len() {
            step(&mut ok, "Int", i, r.Int(), V1_INT[i]);
            i += 1;
        }
        report(&mut failed, ok, " 1", "v1: the ALFG's sequence, five seeds");
    }

    // 2. v1's bounded forms. `n` a power of two takes a mask, anything
    //    else a rejection loop, and the loop is where a port drifts:
    //    reject one value too few and the distribution is biased and the
    //    sequence is shifted.
    {
        let mut ok = true;
        let mut k = 0usize;
        while k < V1_INT63N.len() {
            let (n, want) = V1_INT63N[k];
            let mut r = rand::New(rand::NewSource(1));
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Int63n", i, r.Int63n(n), want[i]);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V1_INT31N.len() {
            let (n, want) = V1_INT31N[k];
            let mut r = rand::New(rand::NewSource(1));
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Int31n", i, r.Int31n(n) as i64, want[i] as i64);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V1_INTN.len() {
            let (n, want) = V1_INTN[k];
            let mut r = rand::New(rand::NewSource(7));
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Intn", i, r.Intn(n), want[i]);
                i += 1;
            }
            k += 1;
        }
        report(
            &mut failed,
            ok,
            " 2",
            "v1: the bounded forms and their rejection",
        );
    }

    // 3. v1's floats, and the two ziggurat generators. NormFloat64 and
    //    ExpFloat64 draw a variable number of values per result, so a
    //    single wrong table entry desynchronises everything after it.
    {
        let mut ok = true;
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_FLOAT64.len() {
            stepf(&mut ok, "Float64", i, r.Float64(), V1_FLOAT64[i]);
            i += 1;
        }
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_FLOAT32.len() {
            stepf(
                &mut ok,
                "Float32",
                i,
                r.Float32() as f64,
                V1_FLOAT32[i] as f64,
            );
            i += 1;
        }
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_NORM.len() {
            stepf(&mut ok, "NormFloat64", i, r.NormFloat64(), V1_NORM[i]);
            i += 1;
        }
        let mut r = rand::New(rand::NewSource(1));
        let mut i = 0usize;
        while i < V1_EXP.len() {
            stepf(&mut ok, "ExpFloat64", i, r.ExpFloat64(), V1_EXP[i]);
            i += 1;
        }
        report(&mut failed, ok, " 3", "v1: floats, and both ziggurats");
    }

    // 4. v1's Perm, Shuffle and Read. A permutation is the sharpest
    //    test of all: it consumes one draw per element and any drift
    //    reorders the whole thing.
    {
        let mut ok = true;
        let mut k = 0usize;
        while k < V1_PERM.len() {
            let (n, want) = V1_PERM[k];
            let mut r = rand::New(rand::NewSource(3));
            let got = r.Perm(n);
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Perm", i, got[i], want[i]);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V1_SHUFFLE.len() {
            let (n, want) = V1_SHUFFLE[k];
            let mut r = rand::New(rand::NewSource(3));
            let mut x: slice<int> = goish::make!([]int, n);
            let mut i = 0i64;
            while i < n {
                x[i as usize] = i;
                i += 1;
            }
            let ptr = x.as_mut_ptr();
            r.Shuffle(n, |a, b| unsafe {
                core::ptr::swap(ptr.offset(a as isize), ptr.offset(b as isize))
            });
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Shuffle", i, x[i], want[i]);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V1_READ.len() {
            let (n, want) = V1_READ[k];
            let mut r = rand::New(rand::NewSource(5));
            let mut b: slice<byte> = goish::make!([]byte, n);
            let (got, err) = r.Read(&mut b);
            if got != n || !err.IsNil() {
                ok = false;
            }
            let mut i = 0usize;
            while i < want.len() {
                stepu(&mut ok, "Read", i, b[i] as u64, want[i] as u64);
                i += 1;
            }
            k += 1;
        }
        report(&mut failed, ok, " 4", "v1: Perm, Shuffle and Read");
    }

    // 5. v2's PCG, straight off the Source. A different generator from
    //    v1's entirely, so none of the numbers above appear here.
    {
        let mut ok = true;
        let mut k = 0usize;
        while k < V2_PCG.len() {
            let (a, b, want) = V2_PCG[k];
            let mut p = randv2::NewPCG(a, b);
            let mut i = 0usize;
            while i < want.len() {
                stepu(&mut ok, "PCG", i, p.Uint64(), want[i]);
                i += 1;
            }
            k += 1;
        }
        let mut r = randv2::New(randv2::NewPCG(1, 2));
        let mut i = 0usize;
        while i < V2_INT64.len() {
            step(&mut ok, "v2 Int64", i, r.Int64(), V2_INT64[i]);
            i += 1;
        }
        let mut r = randv2::New(randv2::NewPCG(1, 2));
        let mut i = 0usize;
        while i < V2_UINT64.len() {
            stepu(&mut ok, "v2 Uint64", i, r.Uint64(), V2_UINT64[i]);
            i += 1;
        }
        let mut r = randv2::New(randv2::NewPCG(1, 2));
        let mut i = 0usize;
        while i < V2_UINT32.len() {
            stepu(
                &mut ok,
                "v2 Uint32",
                i,
                r.Uint32() as u64,
                V2_UINT32[i] as u64,
            );
            i += 1;
        }
        let mut r = randv2::New(randv2::NewPCG(1, 2));
        let mut i = 0usize;
        while i < V2_INT32.len() {
            step(&mut ok, "v2 Int32", i, r.Int32() as i64, V2_INT32[i] as i64);
            i += 1;
        }
        let mut r = randv2::New(randv2::NewPCG(1, 2));
        let mut i = 0usize;
        while i < V2_INT.len() {
            step(&mut ok, "v2 Int", i, r.Int(), V2_INT[i]);
            i += 1;
        }
        report(
            &mut failed,
            ok,
            " 5",
            "v2: the PCG stream and the plain draws",
        );
    }

    // 6. v2's bounded forms, which use Lemire's multiply-and-shift
    //    rather than v1's rejection loop — a different algorithm, so a
    //    port that borrows v1's arithmetic here looks right and is not.
    {
        let mut ok = true;
        let mut k = 0usize;
        while k < V2_INT64N.len() {
            let (n, want) = V2_INT64N[k];
            let mut r = randv2::New(randv2::NewPCG(1, 2));
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Int64N", i, r.Int64N(n), want[i]);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V2_UINT64N.len() {
            let (n, want) = V2_UINT64N[k];
            let mut r = randv2::New(randv2::NewPCG(1, 2));
            let mut i = 0usize;
            while i < want.len() {
                stepu(&mut ok, "Uint64N", i, r.Uint64N(n), want[i]);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V2_UINT32N.len() {
            let (n, want) = V2_UINT32N[k];
            let mut r = randv2::New(randv2::NewPCG(1, 2));
            let mut i = 0usize;
            while i < want.len() {
                stepu(&mut ok, "Uint32N", i, r.Uint32N(n) as u64, want[i] as u64);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V2_INT32N.len() {
            let (n, want) = V2_INT32N[k];
            let mut r = randv2::New(randv2::NewPCG(1, 2));
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "Int32N", i, r.Int32N(n) as i64, want[i] as i64);
                i += 1;
            }
            k += 1;
        }
        let mut k = 0usize;
        while k < V2_INTN.len() {
            let (n, want) = V2_INTN[k];
            let mut r = randv2::New(randv2::NewPCG(1, 2));
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "IntN", i, r.IntN(n), want[i]);
                i += 1;
            }
            k += 1;
        }
        report(&mut failed, ok, " 6", "v2: Lemire's bounded forms");
    }

    // 7. v2's floats, Shuffle, and the marshalled generator state —
    //    the bytes that make a generator resumable, and therefore the
    //    thing that has to be identical for a checkpoint to reload.
    {
        let mut ok = true;
        let mut r = randv2::New(randv2::NewPCG(1, 2));
        let mut i = 0usize;
        while i < V2_FLOAT64.len() {
            stepf(&mut ok, "v2 Float64", i, r.Float64(), V2_FLOAT64[i]);
            i += 1;
        }
        let mut r = randv2::New(randv2::NewPCG(1, 2));
        let mut i = 0usize;
        while i < V2_FLOAT32.len() {
            stepf(
                &mut ok,
                "v2 Float32",
                i,
                r.Float32() as f64,
                V2_FLOAT32[i] as f64,
            );
            i += 1;
        }
        let mut k = 0usize;
        while k < V2_SHUFFLE.len() {
            let (n, want) = V2_SHUFFLE[k];
            let mut r = randv2::New(randv2::NewPCG(1, 2));
            let mut x: slice<int> = goish::make!([]int, n);
            let mut i = 0i64;
            while i < n {
                x[i as usize] = i;
                i += 1;
            }
            let ptr = x.as_mut_ptr();
            r.Shuffle(n, |a, b| unsafe {
                core::ptr::swap(ptr.offset(a as isize), ptr.offset(b as isize))
            });
            let mut i = 0usize;
            while i < want.len() {
                step(&mut ok, "v2 Shuffle", i, x[i], want[i]);
                i += 1;
            }
            k += 1;
        }
        // Go: marshal [112 99 103 58 …] — "pcg:" then the two halves of
        // the state, big-endian.
        let mut p = randv2::NewPCG(1, 2);
        let _ = p.Uint64();
        let (b, err) = p.MarshalBinary();
        if !err.IsNil() || b.len() != V2_MARSHAL.len() {
            ok = false;
        } else {
            let mut i = 0usize;
            while i < V2_MARSHAL.len() {
                stepu(
                    &mut ok,
                    "MarshalBinary",
                    i,
                    b[i] as u64,
                    V2_MARSHAL[i] as u64,
                );
                i += 1;
            }
        }
        // And it resumes: an unmarshalled generator continues where the
        // marshalled one left off, which Go's own reference shows by
        // NOT matching a freshly seeded one.
        let mut q = randv2::NewPCG(0, 0);
        if !q.UnmarshalBinary(&b).IsNil() {
            ok = false;
        }
        let mut p2 = randv2::NewPCG(1, 2);
        let _ = p2.Uint64();
        if q.Uint64() != p2.Uint64() {
            ok = false;
        }
        report(
            &mut failed,
            ok,
            " 7",
            "v2: floats, Shuffle, and a resumable state",
        );
    }

    if failed == 0 {
        fmt::Println!("ok 7/7");
        syscall::Exit(0);
    } else {
        fmt::Println!("FAIL", failed, "of 7");
        syscall::Exit(1);
    }
}
